```javascript
// src/dashboard/static/routes/wren.js

import axios from 'axios';

export default async function handleWrenPrompt(prompt) {
  try {
    const response = await axios.post('http://peer-url/ceo_mind/wren/message', { prompt });
    return response.data.reply;
  } catch (error) {
    console.error('Error forwarding the prompt to Wren:', error);
    throw error;
  }
}
